 function grid(rnd=Math.random,free=false,mode='std',card=0){const strips=free?FSTRIPS[modeOf(mode)][card]:STRIPS[modeOf(mode)];return Array.from({length:COLS},(_,c)=>Array.from({length:ROWS},()=>pick(strips[c],rnd)));}
 const cells=(g,s)=>g.flatMap((a,c)=>a.flatMap((x,r)=>x===s?[[c,r]]:[]));
